PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE files (
    id INTEGER PRIMARY KEY AUTOINCREMENT, path TEXT UNIQUE NOT NULL, media_type TEXT,
    status TEXT DEFAULT 'PENDING', original_size_mb REAL, final_size_mb REAL,
    last_progress INTEGER DEFAULT 0, needs_backup INTEGER DEFAULT 0,
    backup_status TEXT DEFAULT NULL, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, retry_count INTEGER DEFAULT 0, category TEXT DEFAULT 'UNKNOWN', saved_original_path TEXT, percent_saved REAL DEFAULT 0);
CREATE TABLE runtime_state (key TEXT PRIMARY KEY, value TEXT);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_files_category ON files(category);
COMMIT;
